/**
 * Permanently removes rows archived longer ago than the plan's `retentionDays`.
 *
 * Must call (do not reimplement): getPlanLimits, isArchived
 */
import { getPlanLimits } from "@/config/plan-limits";
import { createLogger } from "@/lib/logger";
import { isArchived, retentionCutoff } from "@/lib/soft-delete";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { attachmentStorageMb } from "@/server/services/attachment-service";
import type { JobResult } from "@/server/jobs/types";
import type { IsoTimestamp, OrgId } from "@/types/common";
import { runJob } from "./types";

const ORG_BATCH = 25;
/** Expired issues purged per transaction; the sweep loops until none are left. */
const PURGE_BATCH = 200;

const logger = createLogger("cleanup-archived-job");

/**
 * The retention sweep. Soft-deleted rows are kept for as long as the plan
 * promises and no longer: the cut-off comes from `retentionDays`, so an
 * enterprise tenant keeps years of history where a free one keeps a month.
 *
 * An archived issue past the cut-off has expired: it is deleted for good with
 * its label links, comments and attachments, its and its comments' search
 * documents are dropped, and the attachments' megabytes go back to the storage
 * counter. The audit rows past the window are purged outright.
 */
export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
  return runJob("cleanup-archived", async (result) => {
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const org = await orgRepo.findOrgById(orgId);
      if (!org) continue;

      const { retentionDays } = getPlanLimits(org.plan);
      const cutoff = retentionCutoff(retentionDays, now);

      try {
        result.processed += await purgeExpiredIssues(orgId, cutoff);
      } catch (error) {
        result.failed += 1;
        logger.error("issue purge failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }

      try {
        const purged = await activityRepo.purgeActivityBefore(orgId, cutoff);
        result.processed += purged;
      } catch (error) {
        result.failed += 1;
        logger.error("activity purge failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

/**
 * Purges every issue of one org archived at or before `cutoff`, batch by
 * batch, and returns how many went. Each purged batch disappears from the
 * next listing, so the loop ends once the org has no expired issue left.
 */
async function purgeExpiredIssues(
  orgId: OrgId,
  cutoff: IsoTimestamp,
): Promise<number> {
  let purgedCount = 0;

  for (;;) {
    const expired = (
      await issueRepo.listExpiredIssues(orgId, cutoff, PURGE_BATCH)
    ).filter(isArchived);
    if (expired.length === 0) break;

    const purged = await issueRepo.purgeIssues(
      orgId,
      expired.map((issue) => issue.id),
    );
    if (purged.issueIds.length === 0) break;

    await searchRepo.deleteSearchDocuments(orgId, "issue", purged.issueIds);
    await searchRepo.deleteSearchDocuments(orgId, "comment", purged.commentIds);

    const freedMb = purged.attachmentSizes.reduce(
      (total, sizeBytes) => total + attachmentStorageMb(sizeBytes),
      0,
    );
    if (freedMb > 0) {
      await usageRepo.incrementUsage(orgId, { storageMbUsed: -freedMb });
    }

    purgedCount += purged.issueIds.length;
  }

  return purgedCount;
}

